/** Real generated FileStore intake; ASR/diarization artifacts are controlled fixtures, not model evidence. */
import {join,resolve} from 'node:path';
import {existsSync} from 'node:fs';
import {randomBytes,randomUUID} from 'node:crypto';
import {buildApp} from '../../server/src/app.js';
import {sha256} from '../../server/src/store.js';
const [directory,webRoot]=process.argv.slice(2);if(!directory||!webRoot)throw Error('Private profile and isolated Web root required');
const token=randomBytes(32).toString('hex'),when='2026-10-29T01:00:00Z';let modelCalls=0;
const runtime=await buildApp({dataDir:join(directory,'data'),token,tokenPath:'fixture',host:'127.0.0.1',port:0,maxStorageBytes:20_000_000,maxExportBytes:2_000_000,retentionDays:0,insightIntervalHours:0,allowedOrigins:[],model:'',modelBaseUrl:'',apiKey:'',allowUnauthenticatedLocal:false,embeddingModel:'',embeddingBaseUrl:'',embeddingApiKey:''},{webRoot:resolve(webRoot),backgroundWorker:false,agent:{configured:false,query:async()=>{modelCalls++;throw Error('Recording UI fixture must not call models');},close:async()=>{}}});
runtime.app.addHook('onRequest',async(req,reply)=>{
 if(req.url.includes('/export')&&existsSync(join(directory,'raw-export-fault')))return reply.code(503).send({error:'service_unavailable',message:'Generated raw export unavailable'});
 if(req.url.endsWith('/corrections')&&existsSync(join(directory,'correction-fault')))return reply.code(409).send({error:'conflict',message:'Generated correction conflict'});
 if(req.url.endsWith('/speakers')&&req.method==='POST'&&existsSync(join(directory,'names-fault')))return reply.code(409).send({error:'conflict',message:'Generated current names conflict'});
 if(req.url.includes('/assets?')&&existsSync(join(directory,'sample-fault')))return reply.code(503).send({error:'service_unavailable',message:'Generated sample read unavailable'});
});
const waveform=Buffer.alloc(44+8000*2);waveform.write('RIFF');waveform.writeUInt32LE(waveform.length-8,4);waveform.write('WAVEfmt ',8);waveform.writeUInt32LE(16,16);waveform.writeUInt16LE(1,20);waveform.writeUInt16LE(1,22);waveform.writeUInt32LE(8000,24);waveform.writeUInt32LE(16000,28);waveform.writeUInt16LE(2,32);waveform.writeUInt16LE(16,34);waveform.write('data',36);waveform.writeUInt32LE(16000,40);for(let i=0;i<8000;i++)waveform.writeInt16LE(Math.round(Math.sin(i*Math.PI/20)*1000),44+i*2);
runtime.sources.register({id:'generated-recording',name:'本轮生成录音',kind:'local-files',deviceId:'generated-web',platform:'macos',retention:'archive'});
const begin=runtime.files.begin({sourceId:'generated-recording',item:{externalId:'recording.wav',revision:'1',observedAt:when,kind:'file',layer:'original',mimeType:'audio/wav',title:'资料阅读讨论.wav'},sizeBytes:waveform.length,sha256:sha256(waveform)},()=>{});runtime.files.part(begin.uploadId,0,waveform,()=>{});const recordingId=(await runtime.files.commit(begin.uploadId,()=>{})).id;
const raw=randomUUID(),dialogue=randomUUID(),diarization=randomUUID(),segments=[{startMs:0,endMs:400,text:'本轮生成的原始转写：先核对资料。',speaker:'SPEAKER_0'},{startMs:400,endMs:800,text:'继续核对返回路径。',speaker:'SPEAKER_0',uncertain:true},{startMs:800,endMs:1000,text:'保留原始录音和转写。',speaker:'SPEAKER_1'}];
for(const [artifact,kind,value]of [[raw,'transcript',{complete:true,transcript:{durationMs:1000,segments}}],[dialogue,'dialogue',{complete:true,transcript:{durationMs:1000,segments},inputArtifacts:[raw]}],[diarization,'diarization',{durationMs:1000,segments:segments.map(({startMs,endMs,speaker})=>({startMs,endMs,speaker})),samples:[{speaker:'SPEAKER_0'},{speaker:'SPEAKER_1'}],warnings:[],observedSpeakers:2}]] as const)runtime.store.db.prepare('INSERT INTO file_artifacts VALUES(?,?,?,?,?,?,1)').run(artifact,recordingId,kind,when,'generated-controlled-ASR',JSON.stringify(value));
for(const [index,segment]of segments.entries())runtime.store.db.prepare('INSERT INTO file_chunks(id,artifact_id,capture_id,start_ms,end_ms,text,metadata,ordinal) VALUES(?,?,?,?,?,?,?,?)').run(randomUUID(),dialogue,recordingId,segment.startMs,segment.endMs,segment.text,JSON.stringify({speaker:segment.speaker,uncertain:segment.uncertain}),index);
for(const speaker of ['SPEAKER_0','SPEAKER_1'])runtime.files.saveAsset(diarization,'speaker_samples/'+speaker+'.wav','audio/wav',waveform);
runtime.store.db.prepare("UPDATE file_jobs SET state='succeeded',summary_state='skipped',error=NULL WHERE capture_id=?").run(recordingId);
runtime.sources.register({id:'generated-calendar',name:'Generated calendar',kind:'custom',deviceId:'generated-web',platform:'import',retention:'snapshot'});
const calendar=await runtime.sources.upsert('generated-calendar',{externalId:'generated-session',revision:'1',observedAt:when,title:'Generated confirmed linked session',kind:'calendar',layer:'snapshot',text:'Generated exact planned session original',calendar:{start:when,end:'2026-10-29T02:00:00Z',allDay:false,timeZone:'UTC',status:'confirmed'}});
// Controlled already-confirmed linkage receipt; no proposal/model run is claimed.
runtime.store.db.prepare('INSERT INTO file_artifacts VALUES(?,?,?,?,?,?,1)').run(randomUUID(),recordingId,'calendar-link',when,'generated-confirmed-link',JSON.stringify({calendarId:calendar.id,title:'Generated confirmed linked session',calendar:{start:when,end:'2026-10-29T02:00:00Z',timeZone:'UTC'},confirmed:true}));
const provider=await runtime.files.transcriptRevision('generated-recording',{externalId:'provider-transcript',kind:'file',title:'Generated provider transcript only',observedAt:when},'Exact provider original export',{durationMs:1000,coverage:'full',engine:'generated-provider',segments:[{startMs:0,endMs:1000,text:'Generated literal provider transcript',speaker:'Vendor A'}]},()=>{});
await runtime.app.listen({host:'127.0.0.1',port:0});console.log(JSON.stringify({server:runtime.app.server.address(),token,recordingId,providerId:provider.id,calendarId:calendar.id,generatedOnly:true,modelCalls}));process.on('SIGTERM',()=>{void runtime.app.close().then(()=>process.exit(0));});
